/**
 * Phase 11 FROZEN cross-worker contracts (@planmo/packs).
 *
 * Do NOT edit this file during implementation — the workers implement
 * against these signatures. When implementations land, the lead deletes
 * the `declare` stubs (keeping only types/interfaces) before wiring the
 * barrel in index.ts (TS2308 collision guard).
 *
 * Owned tasks: P11-01 trust model (trust.ts), P11-02 catalog/source
 * abstraction (catalog.ts), P11-03 checksums/pinning/reversibility
 * (install.ts), P11-05 GitHub export prototype (github-export.ts).
 */
import type { Checksum, LockfileDocument, PackLockEntry, PackProvenance, TrustLevel } from '@planmo/schema';
import type { LoadedPack } from './loader.js';
import type { ResolutionResult } from './resolve.js';

// ------------------------------------------------------------------ trust (P11-01)

/** Input to the deterministic trust classifier. */
export interface TrustInput {
  /** Where the pack content actually came from. */
  source: 'builtin' | 'local' | 'git' | 'registry';
  /** Parsed provenance for remote packs; absent for builtin/local. */
  provenance?: PackProvenance;
  /** Effective catalogue trust level after classification. */
  declaredTrust?: TrustLevel;
}

/** Deterministic trust classification for one pack. */
export interface TrustClassification {
  trustLevel: TrustLevel;
  /** Remote non-verified packs ALWAYS require review (cannot be disabled). */
  requiresReview: boolean;
  /** Stable human-readable reasons, sorted, one per decision. */
  reasons: readonly string[];
}

/** Classify a pack's trust level + review burden (REQ-TRUST-001/002). */
export declare function classifyTrust(input: TrustInput): TrustClassification;

/** Deterministic one-line trust summary for reports/CLI. */
export declare function formatTrust(classification: TrustClassification): string;

// --------------------------------------------------------- catalog (P11-02)

/** Declarative pack source descriptor (opt-in; nothing fetchable by default). */
export interface CatalogSource {
  /** Stable source id, e.g. "local-packs", "community-registry-a". */
  id: string;
  kind: 'local-dir' | 'registry' | 'git';
  /** URL for registry/git; directory path for local-dir. */
  url: string;
  /** Git ref when kind == 'git'. */
  ref?: string;
  /** Trust level as DECLARED by the source owner; classifier validates. */
  declaredTrust: TrustLevel;
}

/** One resolvable catalog entry discovered through a source. */
export interface CatalogEntry {
  sourceId: string;
  sourceKind: CatalogSource['kind'];
  ref: string;
  version: string;
  /** sha256 of the raw resolved content (never optional for remote). */
  integritySha256?: string;
  provenance?: PackProvenance;
  /** Body text of the resolved pack.yml (for the loader). */
  raw: string;
}

/** Injected fetch/read interface — the engine itself never touches I/O. */
export interface CatalogFetcher {
  /** Fetch a URL/path to its raw text. Throws on any failure. */
  fetchText(this: void, url: string): Promise<string>;
  /** List resolvable refs under a URL/path (registry index or dir). */
  listRefs(this: void, url: string): Promise<readonly string[]>;
}

/** Resolve declared sources into entries (integrity verified per remote entry). */
export declare function resolveCatalog(
  sources: readonly CatalogSource[],
  fetcher: CatalogFetcher,
): Promise<readonly CatalogEntry[]>;

/** Deterministic selection: pinned version > highest valid version. */
export declare function pickCatalogEntry(
  entries: readonly CatalogEntry[],
  ref: string,
  version?: string,
): CatalogEntry | null;

// -------------------------------------------------- install & verify (P11-03)

/** One row of an install/update diff. */
export interface InstallDiffRow {
  ref: string;
  action: 'added' | 'removed' | 'updated' | 'unchanged';
  from?: { version: string; integrity?: string };
  to?: { version: string; integrity?: string };
}

/** Diffable, reversible install/update plan (never mutates anything). */
export interface InstallPlan {
  rows: readonly InstallDiffRow[];
  /** True when every action is reversible (always true in v1 — plan-only). */
  reversible: boolean;
  /** Deterministic unified-ish text render of the diff lines. */
  diff: string;
}

/** Diff two lockfiles into a reversible install/update plan (P11-03). */
export declare function planLockDiff(
  from: LockfileDocument | null,
  to: LockfileDocument,
): InstallPlan;

/** Verify every lock entry's integrity against actual resolved content. */
export declare function verifyLockIntegrity(
  lock: LockfileDocument,
  readContent: (entry: PackLockEntry) => Promise<string>,
): Promise<{ ok: boolean; failures: readonly string[] }>;

/** Build the "next" lock for `refs` from a deterministic resolution. */
export declare function lockFromResolution(
  result: ResolutionResult,
  planmoVersion: string,
): LockfileDocument;

// ------------------------------------------------- github export (P11-05)

/** One file in the additive GitHub export payload. */
export interface ExportFile {
  path: string;
  content: string;
}

/** Additive export payload — rendered only; no network, no core dependency. */
export interface GithubExportPayload {
  owner: string;
  repo: string;
  branch: string;
  title: string;
  body: string;
  files: readonly ExportFile[];
}

/** Render an additive GitHub export payload from planning artifacts (P11-05). */
export declare function renderGithubExport(input: {
  owner: string;
  repo: string;
  branch: string;
  summaryLines: readonly string[];
  files: readonly ExportFile[];
}): GithubExportPayload;

export type { Checksum, LockfileDocument, PackLockEntry, PackProvenance, TrustLevel, LoadedPack, ResolutionResult };